// "Check the output" (AS-3.8, Anthropic Commercial Terms D.3: tell users to verify outputs). Shown under each settled
// answer and summary, and inside the draft band. Not part of any export: a letter must not carry it to the other side.
export const CHECK_OUTPUT_TEXT =
  'Generated by AI. Check it against the cited passages before you rely on it. Not legal advice.'

export function CheckOutputNote({ className }: { className?: string }) {
  return (
    <p role="note" className={className ?? 'mt-3 text-[12.5px] leading-snug text-fg-subtle'}>
      {CHECK_OUTPUT_TEXT}
    </p>
  )
}
